from __future__ import annotations

import json
import re
from pathlib import Path

ROOT = Path('.')


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding='utf-8')
    if old not in text:
        raise RuntimeError(f'missing patch target in {path}: {old[:120]!r}')
    target.write_text(text.replace(old, new, 1), encoding='utf-8')


# ---------------------------------------------------------------------------
# 1. Decimal/date-safe sentence segmentation shared by backend claims.
# ---------------------------------------------------------------------------
(ROOT / 'src/semantic_prompt_transfer/sentence_utils.py').write_text(
    '''from __future__ import annotations\n\nfrom collections.abc import Iterator\n\n\ndef sentence_spans(text: str) -> Iterator[tuple[int, int]]:\n    \"\"\"Yield sentence spans without treating decimal/date dots as boundaries.\n\n    Newlines are hard boundaries. A dot between two digits is protected so values such\n    as 58.3%, 134.0%, 2026.03.23 and 3.14 remain inside one claim.\n    \"\"\"\n    value = str(text or \"\")\n    start = 0\n    index = 0\n    length = len(value)\n    while index < length:\n        char = value[index]\n        if char == \"\\n\":\n            if start < index and value[start:index].strip():\n                yield start, index\n            index += 1\n            start = index\n            continue\n        if char in \".!?\":\n            if (\n                char == \".\"\n                and index > 0\n                and index + 1 < length\n                and value[index - 1].isdigit()\n                and value[index + 1].isdigit()\n            ):\n                index += 1\n                continue\n            end = index + 1\n            while end < length and value[end] in \".!?\":\n                end += 1\n            if value[start:end].strip():\n                yield start, end\n            start = end\n            index = end\n            continue\n        index += 1\n    if start < length and value[start:].strip():\n        yield start, length\n''',
    encoding='utf-8',
)

path = ROOT / 'src/semantic_prompt_transfer/verification_flow.py'
text = path.read_text(encoding='utf-8')
text = text.replace('from .llm import TextGenerator\n', 'from .llm import TextGenerator\nfrom .sentence_utils import sentence_spans\n', 1)
old = '''        for match in _SENTENCE.finditer(str(text or "")):\n            raw = match.group(0)\n            if not raw.strip() or raw.isspace():\n                continue\n            counter += 1\n            evidence_ids = tuple(\n                value for value in dict.fromkeys(_CITATION.findall(raw))\n                if value in allowed\n            )\n            claims.append(\n                Claim(\n                    claim_id=f"{item.value}-{counter:03d}",\n                    review_item=item,\n                    text=raw,\n                    start=match.start(),\n                    end=match.end(),\n                    evidence_ids=evidence_ids,\n                )\n            )\n'''
new = '''        source = str(text or "")\n        for start, end in sentence_spans(source):\n            raw = source[start:end]\n            if not raw.strip():\n                continue\n            counter += 1\n            evidence_ids = tuple(\n                value for value in dict.fromkeys(_CITATION.findall(raw))\n                if value in allowed\n            )\n            claims.append(\n                Claim(\n                    claim_id=f"{item.value}-{counter:03d}",\n                    review_item=item,\n                    text=raw,\n                    start=start,\n                    end=end,\n                    evidence_ids=evidence_ids,\n                )\n            )\n'''
if old not in text:
    raise RuntimeError('ClaimSegmenter patch target missing')
text = text.replace(old, new, 1)

# ---------------------------------------------------------------------------
# 2. Section-batch verifier: one Gemma verifier call per review item.
# ---------------------------------------------------------------------------
marker = '    def verify(self, claim: Claim, evidence: Iterable[EvidenceRecord]) -> VerificationFinding:\n'
insert_at = text.index(marker, text.index('class LLMVerificationAgent'))
batch_method = '''    def _coerce_batch_finding(\n        self,\n        claim: Claim,\n        value: dict[str, Any],\n        rows: tuple[EvidenceRecord, ...],\n    ) -> VerificationFinding:\n        allowed_ids = {row.evidence_id for row in rows}\n        try:\n            status = VerificationStatus(str(value.get("status") or "WARN").upper())\n            severity = RepairSeverity(str(value.get("severity") or "MINOR").upper())\n        except Exception:\n            return self._warn(claim, "VERIFIER_BATCH_SCHEMA_ERROR", "검증 LLM 배치 응답 스키마 오류")\n        problem_span = str(value.get("problem_span") or "")\n        reason_code = str(value.get("reason_code") or "").upper()\n        reason = str(value.get("reason") or "")\n        evidence_ids = tuple(\n            eid for eid in (str(v) for v in value.get("evidence_ids", [])) if eid in allowed_ids\n        )\n        repair_instruction = str(value.get("repair_instruction") or "")\n        if status is VerificationStatus.FAIL:\n            if not rows:\n                return VerificationFinding(\n                    claim.claim_id, claim.revision, VerificationStatus.INSUFFICIENT_EVIDENCE,\n                    reason_code="NO_EVIDENCE", reason="검증에 사용할 근거가 없음",\n                )\n            if reason_code not in self._FAIL_REASON_CODES:\n                return self._warn(claim, "UNSAFE_FAIL_REASON", reason or "FAIL 사유가 허용 범위를 벗어남")\n            if severity is not RepairSeverity.MINOR:\n                return self._warn(claim, "AUTO_PATCH_SCOPE_TOO_WIDE", "문장/문단 재작성은 자동 반영하지 않음")\n            if not problem_span or problem_span not in claim.text:\n                return self._warn(claim, "INVALID_FAIL_SPAN", "FAIL이지만 원문 problem_span을 특정하지 못함")\n            if not evidence_ids:\n                return VerificationFinding(\n                    claim.claim_id, claim.revision, VerificationStatus.INSUFFICIENT_EVIDENCE,\n                    reason_code="UNBOUND_FAIL_EVIDENCE", reason="FAIL 판정을 특정 근거에 연결하지 못함",\n                )\n        if status is VerificationStatus.INSUFFICIENT_EVIDENCE:\n            problem_span = ""\n            repair_instruction = ""\n        if status in {VerificationStatus.PASS, VerificationStatus.WARN}:\n            repair_instruction = ""\n        return VerificationFinding(\n            claim_id=claim.claim_id,\n            revision=claim.revision,\n            status=status,\n            severity=severity,\n            problem_span=problem_span,\n            reason_code=reason_code,\n            reason=reason,\n            evidence_ids=evidence_ids,\n            repair_instruction=repair_instruction,\n        )\n\n    def verify_many(\n        self,\n        claims: Iterable[Claim],\n        evidence_by_claim: Iterable[Iterable[EvidenceRecord]],\n    ) -> tuple[VerificationFinding, ...]:\n        claim_rows = tuple(claims)\n        evidence_rows = tuple(tuple(rows) for rows in evidence_by_claim)\n        if len(claim_rows) != len(evidence_rows):\n            raise ValueError("claims and evidence_by_claim length mismatch")\n        if not claim_rows:\n            return ()\n        catalog: dict[str, str] = {}\n        payload = []\n        for claim, rows in zip(claim_rows, evidence_rows, strict=True):\n            ids = []\n            for row in rows:\n                catalog.setdefault(row.evidence_id, str(row.content or "")[:1400])\n                ids.append(row.evidence_id)\n            payload.append({\n                "claim_id": claim.claim_id,\n                "revision": claim.revision,\n                "claim": claim.text,\n                "evidence_ids": ids,\n            })\n        messages = [\n            {\n                "role": "system",\n                "content": (\n                    "당신은 기업여신 심사의견의 독립 검증 에이전트다. 여러 claim을 한 번에 검증하되 "\n                    "최종 문장을 직접 작성하거나 문체를 개선하지 않는다. 기본 판단은 PASS다. FAIL은 "\n                    "근거와 직접 대조해 값·기간·단위·동일 사실이 명백히 충돌하는 경우에만 허용한다. "\n                    "애매함·근거 부족·표현 선호·분석 강도 차이는 WARN 또는 INSUFFICIENT_EVIDENCE다. "\n                    "FAIL이면 severity=MINOR, problem_span은 claim 원문에서 그대로 복사하고 실제 evidence_id만 사용한다. "\n                    "reason_code는 FACT_CONTRADICTION, PERIOD_MISMATCH, UNIT_MISMATCH, SOURCE_CONFLICT 중 하나만 사용한다. "\n                    "JSON 객체 하나만 반환한다. corrected_sentence는 작성하지 않는다."\n                ),\n            },\n            {\n                "role": "user",\n                "content": json.dumps(\n                    {\n                        "claims": payload,\n                        "evidence": catalog,\n                        "output_schema": {\n                            "findings": [{\n                                "claim_id": "A-001", "revision": 1, "status": "PASS",\n                                "severity": "MINOR", "problem_span": "", "reason_code": "",\n                                "reason": "", "evidence_ids": [], "repair_instruction": ""\n                            }]\n                        },\n                    },\n                    ensure_ascii=False,\n                    separators=(",", ":"),\n                ),\n            },\n        ]\n        try:\n            raw = str(self.generator.generate(messages) or "").strip().strip("`")\n            match = re.search(r"\\{.*\\}", raw, flags=re.S)\n            if not match:\n                raise ValueError("missing JSON object")\n            decoded = json.loads(match.group(0))\n            values = decoded.get("findings") if isinstance(decoded, dict) else None\n            if not isinstance(values, list):\n                raise ValueError("missing findings array")\n            by_claim = {str(row.get("claim_id") or ""): row for row in values if isinstance(row, dict)}\n        except Exception as exc:\n            return tuple(\n                self._warn(claim, "VERIFIER_BATCH_PARSE_ERROR", f"검증 LLM 배치 파싱 실패: {type(exc).__name__}")\n                for claim in claim_rows\n            )\n        results = []\n        for claim, rows in zip(claim_rows, evidence_rows, strict=True):\n            value = by_claim.get(claim.claim_id)\n            if value is None:\n                results.append(self._warn(claim, "VERIFIER_BATCH_MISSING", "검증 LLM이 해당 claim 판정을 반환하지 않음"))\n            else:\n                results.append(self._coerce_batch_finding(claim, value, rows))\n        return tuple(results)\n\n'''
text = text[:insert_at] + batch_method + text[insert_at:]
path.write_text(text, encoding='utf-8')

# ---------------------------------------------------------------------------
# 3. E5 A-E batch query encoding.
# ---------------------------------------------------------------------------
path = ROOT / 'src/semantic_prompt_transfer/poc_processing.py'
text = path.read_text(encoding='utf-8')
start = text.index('    def search(self, query: str, **kwargs: Any) -> dict[str, Any]:', text.index('class ShardedAttachmentRetriever'))
replacement = '''    def _from_embedding(\n        self,\n        query: str,\n        embedding: np.ndarray,\n        filters: dict[str, Any],\n    ) -> dict[str, Any]:\n        raw = self.vector_store.search(embedding, top_k=max(self.top_k * 4, self.top_k), filters=filters)\n        if not raw:\n            return {"query": query, "filters": filters, "hits": [], "retrieval_quality": "empty"}\n        best = float(raw[0].get("score") or 0.0)\n        floor = max(0.10, best - 0.12)\n        accepted: list[dict[str, Any]] = []\n        seen: set[str] = set()\n        for hit in raw:\n            score = float(hit.get("score") or 0.0)\n            if score < floor:\n                continue\n            key = self._dedupe_key(hit)\n            if key in seen:\n                continue\n            seen.add(key)\n            row = dict(hit)\n            row["relevance_status"] = "accepted"\n            accepted.append(row)\n            if len(accepted) >= self.top_k:\n                break\n        quality = "accepted" if accepted else "low_relevance"\n        return {\n            "query": query,\n            "filters": filters,\n            "hits": accepted,\n            "retrieval_quality": quality,\n            "best_score": best,\n            "score_floor": floor,\n            "raw_hit_count": len(raw),\n        }\n\n    def search(self, query: str, **kwargs: Any) -> dict[str, Any]:\n        filters = dict(kwargs.get("filters") or {})\n        missing = [key for key in ("tenant_id", "case_id") if not filters.get(key)]\n        if missing:\n            raise ValueError(f"POC retrieval requires scope filters: {missing}")\n        embedding = self.encoder.encode_queries([query])[0]\n        return self._from_embedding(query, embedding, filters)\n\n    def search_many(self, queries: list[str] | tuple[str, ...], **kwargs: Any) -> list[dict[str, Any]]:\n        values = [str(query) for query in queries]\n        if not values:\n            return []\n        filters = dict(kwargs.get("filters") or {})\n        missing = [key for key in ("tenant_id", "case_id") if not filters.get(key)]\n        if missing:\n            raise ValueError(f"POC retrieval requires scope filters: {missing}")\n        embeddings = np.asarray(self.encoder.encode_queries(values), dtype=np.float32)\n        if len(embeddings) != len(values):\n            raise RuntimeError("query embedding batch length mismatch")\n        return [\n            self._from_embedding(query, embeddings[index], filters)\n            for index, query in enumerate(values)\n        ]\n'''
text = text[:start] + replacement + '\n'
path.write_text(text, encoding='utf-8')

# ---------------------------------------------------------------------------
# 4. Few-shot placeholder leakage: remove bracket placeholders at the source.
# ---------------------------------------------------------------------------
path = ROOT / 'src/semantic_prompt_transfer/review.py'
text = path.read_text(encoding='utf-8')
text = text.replace('value = value.replace(token, "[ENTITY]")', 'value = value.replace(token, "특정대상")')
text = text.replace('value = _COMPANY.sub("[COMPANY]", value)', 'value = _COMPANY.sub("특정기업", value)')
text = text.replace('"[DATE]", value)', '"특정일자", value)')
text = text.replace('"[PERIOD]", value)', '"특정기간", value)')
text = text.replace('value = _NUMBER.sub("[VALUE]", value)', 'value = _NUMBER.sub("수치", value)')
text = text.replace(
    '"FEW SHOT은 수치·회사명·기간을 제거한 "\n            "문체와 분석 구조만 참고한다. 금액은 CURRENT_CASE_EVIDENCE에 표시된 정규화 단위를 그대로 사용한다. "',
    '"FEW SHOT은 수치·회사명·기간을 일반화한 문체와 분석 구조만 참고하며 STYLE_ONLY의 일반화 표현을 최종 답변에 복사하지 않는다. "\n            "금액은 CURRENT_CASE_EVIDENCE에 표시된 정규화 단위를 그대로 사용한다. "',
)
path.write_text(text, encoding='utf-8')

# ---------------------------------------------------------------------------
# 5. Orchestrator: placeholder guard, E5 batch retrieval, batch verification,
#    and generation/verification overlap on two logical vLLM lanes.
# ---------------------------------------------------------------------------
path = ROOT / 'src/semantic_prompt_transfer/orchestration.py'
text = path.read_text(encoding='utf-8')
text = text.replace('import re\nimport uuid\n', 'import re\nimport uuid\nfrom concurrent.futures import ThreadPoolExecutor\n', 1)
text = text.replace(
    '_INCOMPLETE_SUFFIXES = ("등에", "으로", "하며", "하고", "및", "따라", "대해", "대한", "에서", "위해", "통해", "반면", "이나", "지만", "경우", "때문에")\n',
    '_INCOMPLETE_SUFFIXES = ("등에", "으로", "하며", "하고", "및", "따라", "대해", "대한", "에서", "위해", "통해", "반면", "이나", "지만", "경우", "때문에")\n_STYLE_PLACEHOLDER = re.compile(r"\\[(?:VALUE|PERIOD|COMPANY|DATE|ENTITY)\\]", re.IGNORECASE)\n',
    1,
)
# Add placeholder cleanup before _cited_ids.
insert_point = text.index('    @staticmethod\n    def _cited_ids')
cleanup_method = '''    @staticmethod\n    def _strip_style_placeholder_leakage(text: str) -> str:\n        value = str(text or "")\n        if not _STYLE_PLACEHOLDER.search(value):\n            return value.strip()\n        clean_lines = [line for line in value.splitlines() if not _STYLE_PLACEHOLDER.search(line)]\n        cleaned = "\\n".join(clean_lines).strip()\n        if cleaned:\n            return cleaned\n        return _STYLE_PLACEHOLDER.sub("", value).strip()\n\n'''
text = text[:insert_point] + cleanup_method + text[insert_point:]
text = text.replace(
    '            if text:\n                text = self._ensure_complete(',
    '            if text:\n                text = self._strip_style_placeholder_leakage(text)\n                text = self._ensure_complete(',
    1,
)
# retry path
retry_target = '''                text = self._generate_once(generator, prompt.messages)\n                if text:\n                    text = self._ensure_complete(\n'''
retry_repl = '''                text = self._generate_once(generator, prompt.messages)\n                if text:\n                    text = self._strip_style_placeholder_leakage(text)\n                    text = self._ensure_complete(\n'''
if retry_target not in text:
    raise RuntimeError('retry placeholder guard target missing')
text = text.replace(retry_target, retry_repl, 1)

# batch verifier path
old_findings = '''        findings: list[tuple[Any, Any]] = []\n        by_id = {row.evidence_id: row for row in evidence}\n        for claim in claims:\n            claim_evidence = [by_id[eid] for eid in claim.evidence_ids if eid in by_id] or list(evidence)\n            if claim_callback:\n                claim_callback(\n                    item,\n                    {"type": "verification_started", "claim_id": claim.claim_id, "revision": claim.revision},\n                )\n            finding = self.verifier.verify(claim, claim_evidence)\n            findings.append((claim, finding))\n            if claim_callback:\n                claim_callback(item, {"type": "verification_result", **finding.to_dict()})\n\n'''
new_findings = '''        findings: list[tuple[Any, Any]] = []\n        by_id = {row.evidence_id: row for row in evidence}\n        claim_evidence_rows: list[list[EvidenceRecord]] = []\n        for claim in claims:\n            claim_evidence = [by_id[eid] for eid in claim.evidence_ids if eid in by_id] or list(evidence)\n            claim_evidence_rows.append(claim_evidence)\n            if claim_callback:\n                claim_callback(\n                    item,\n                    {"type": "verification_started", "claim_id": claim.claim_id, "revision": claim.revision},\n                )\n        batch_verify = getattr(self.verifier, "verify_many", None)\n        batch_results = None\n        if callable(batch_verify) and claims:\n            try:\n                candidate = tuple(batch_verify(claims, claim_evidence_rows))\n                if len(candidate) == len(claims):\n                    batch_results = candidate\n            except Exception:\n                batch_results = None\n        if batch_results is None:\n            batch_results = tuple(\n                self.verifier.verify(claim, claim_evidence)\n                for claim, claim_evidence in zip(claims, claim_evidence_rows, strict=True)\n            )\n        for claim, finding in zip(claims, batch_results, strict=True):\n            findings.append((claim, finding))\n            if claim_callback:\n                claim_callback(item, {"type": "verification_result", **finding.to_dict()})\n\n'''
if old_findings not in text:
    raise RuntimeError('verification loop patch target missing')
text = text.replace(old_findings, new_findings, 1)

# Batch A-E retrieval.
old_prepare = '''            prepared: dict[ReviewItem, tuple[str, list[EvidenceRecord], list[Any]]] = {}\n            evidence_by_item: dict[ReviewItem, list[EvidenceRecord]] = {}\n            for index, item in enumerate(ReviewItem.ordered()):\n                query = self.query_profiles.get(item).build(case)\n                try:\n                    retrieval = self.attachment_retriever.search(\n                        query,\n                        filters={"tenant_id": case.tenant_id, "case_id": case.case_id},\n                    )\n                except Exception as exc:\n                    recovered_any = True\n                    retrieval = {"query": query, "hits": [], "recovered": True}\n                    self._audit(case, job_id, "RETRIEVAL_RECOVERED", {"item": item.value, "error_type": type(exc).__name__, "message": str(exc)[:1000]})\n                try:\n                    evidence = self.evidence_assembler.assemble(item, credit_facts, retrieval)\n                except Exception as exc:\n                    recovered_any = True\n                    evidence = self.evidence_assembler.assemble(item, credit_facts, {"hits": []}) if credit_facts else []\n                    self._audit(case, job_id, "EVIDENCE_ASSEMBLY_RECOVERED", {"item": item.value, "error_type": type(exc).__name__, "message": str(exc)[:1000]})\n                try:\n                    examples = list(self.few_shot_selector.select(\n                        item,\n                        loan_type=case.loan_type,\n                        industry_code=case.industry_code,\n                        situation_tags=case.situation_tags,\n                    ))\n                except Exception as exc:\n                    recovered_any = True\n                    examples = []\n                    self._audit(case, job_id, "FEW_SHOT_SELECTION_RECOVERED", {"item": item.value, "message": str(exc)[:1000]})\n                prepared[item] = (query, evidence, examples)\n                evidence_by_item[item] = evidence\n                emit(JobStage.ATTACHMENT_RETRIEVAL, 27 + index * 2, f"{item.value}. 관련 근거 검색 완료", item)\n\n'''
new_prepare = '''            prepared: dict[ReviewItem, tuple[str, list[EvidenceRecord], list[Any]]] = {}\n            evidence_by_item: dict[ReviewItem, list[EvidenceRecord]] = {}\n            ordered_items = ReviewItem.ordered()\n            queries = {item: self.query_profiles.get(item).build(case) for item in ordered_items}\n            retrieval_by_item: dict[ReviewItem, dict[str, Any]] = {}\n            bulk_search = getattr(self.attachment_retriever, "search_many", None)\n            if callable(bulk_search):\n                try:\n                    bulk_rows = list(bulk_search(\n                        [queries[item] for item in ordered_items],\n                        filters={"tenant_id": case.tenant_id, "case_id": case.case_id},\n                    ))\n                    if len(bulk_rows) == len(ordered_items):\n                        retrieval_by_item = dict(zip(ordered_items, bulk_rows, strict=True))\n                except Exception as exc:\n                    self._audit(case, job_id, "BATCH_RETRIEVAL_FALLBACK", {"error_type": type(exc).__name__, "message": str(exc)[:1000]})\n            for index, item in enumerate(ordered_items):\n                query = queries[item]\n                retrieval = retrieval_by_item.get(item)\n                if retrieval is None:\n                    try:\n                        retrieval = self.attachment_retriever.search(\n                            query,\n                            filters={"tenant_id": case.tenant_id, "case_id": case.case_id},\n                        )\n                    except Exception as exc:\n                        recovered_any = True\n                        retrieval = {"query": query, "hits": [], "recovered": True}\n                        self._audit(case, job_id, "RETRIEVAL_RECOVERED", {"item": item.value, "error_type": type(exc).__name__, "message": str(exc)[:1000]})\n                try:\n                    evidence = self.evidence_assembler.assemble(item, credit_facts, retrieval)\n                except Exception as exc:\n                    recovered_any = True\n                    evidence = self.evidence_assembler.assemble(item, credit_facts, {"hits": []}) if credit_facts else []\n                    self._audit(case, job_id, "EVIDENCE_ASSEMBLY_RECOVERED", {"item": item.value, "error_type": type(exc).__name__, "message": str(exc)[:1000]})\n                try:\n                    examples = list(self.few_shot_selector.select(\n                        item,\n                        loan_type=case.loan_type,\n                        industry_code=case.industry_code,\n                        situation_tags=case.situation_tags,\n                    ))\n                except Exception as exc:\n                    recovered_any = True\n                    examples = []\n                    self._audit(case, job_id, "FEW_SHOT_SELECTION_RECOVERED", {"item": item.value, "message": str(exc)[:1000]})\n                prepared[item] = (query, evidence, examples)\n                evidence_by_item[item] = evidence\n                emit(JobStage.ATTACHMENT_RETRIEVAL, 27 + index * 2, f"{item.value}. 관련 근거 검색 완료", item)\n\n'''
if old_prepare not in text:
    raise RuntimeError('prepared retrieval patch target missing')
text = text.replace(old_prepare, new_prepare, 1)

# Overlap section generation with previous-section verification.
start = text.index('            sections: list[ReviewSectionDraft] = []\n            trace = EvidenceTraceLedger()')
